use std::fs;
use std::path::PathBuf;

use hotpath_core::agent_compatibility::{
    NewlanguageObjectRole, NewlanguageRuntimeProfile, NewlanguageRuntimeSelector,
    NewlanguageRuntimeVerificationDocumentKind,
};
use hotpath_core::dag::Cid;
use hotpath_launcher::newlanguage_verification_collector::collect_newlanguage_verification_document;

#[test]
#[ignore = "requires an explicitly pinned newlanguage producer binary and object store"]
fn immutable_producer_resolved_composition_crosses_the_bounded_launcher_boundary() {
    let executable = required_path("HOTPATH_NEWLANGUAGE_PRODUCER_EXE");
    let store = required_path("HOTPATH_NEWLANGUAGE_PRODUCER_STORE");
    let composition = std::env::var("HOTPATH_NEWLANGUAGE_RESOLVED_COMPOSITION_CID")
        .expect("exact producer resolved-composition CID is required");
    let executable_bytes = fs::read(&executable).expect("producer executable must be readable");
    let profile = NewlanguageRuntimeProfile::new(
        NewlanguageRuntimeSelector::resume_state_revision(external('9')).unwrap(),
        "resolved-composition.verifier",
        Cid::blake3(&executable_bytes),
    )
    .unwrap();
    let binding = profile
        .observe_runtime_executable(executable)
        .unwrap()
        .into_verification_launch_binding(
            store,
            NewlanguageRuntimeVerificationDocumentKind::ResolvedComposition,
            composition.clone(),
        )
        .unwrap();
    assert_eq!(binding.subject().external_cid(), composition);
    assert_eq!(
        binding.subject().role(),
        NewlanguageObjectRole::ResolvedExecutionComposition
    );

    let collected = collect_newlanguage_verification_document(binding).unwrap();
    assert!(collected.process_spawned());
    assert!(collected.child_reaped());
    assert!(!collected.shell_inserted());
    assert!(!collected.parent_environment_inherited());
    assert!(!collected.runtime_session_admitted());
    assert!(!collected.frontier_mutated());
    assert!(!collected.execution_authorized());

    let observed = collected.observe_resolved_composition().unwrap();
    assert_eq!(observed.resolved_composition().external_cid(), composition);
    assert!(observed.semantic_closure_verified());
    assert!(observed.matches_current_runtime_protocol());
    assert!(observed.local_provision_required_before_execution());
    assert!(!observed.local_provision_verified());
    assert!(!observed.observed_execution_bound());
    assert!(!observed.authority_granted());
    assert!(!observed.currentness_established());
    assert!(!observed.default_deployed());
    observed.verify_integrity().unwrap();
}

fn required_path(name: &str) -> PathBuf {
    let path = PathBuf::from(std::env::var_os(name).expect("required path environment is missing"));
    assert!(path.is_absolute(), "required path must be absolute");
    assert!(path.exists(), "required path must exist");
    path
}

fn external(byte: char) -> String {
    format!("ucx1b3{}", byte.to_string().repeat(64))
}

