function allTextScalarsAllowed(text: string): boolean {
  return Array.from(text).every((character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    const control = codePoint <= 0x1f || (codePoint >= 0x7f && codePoint <= 0x9f);
    return !control || character === '\n' || character === '\r' || character === '\t';
  });
}

function boundedPreview(text: string): string {
  let preview = '';
  let used = 0;
